parameters.jsonBody:
={{ JSON.stringify({
  model: 'claude-haiku-5-5',
  max_tokens: 400,
  system: [
    'You sort phone screenshots for a storage-cleanup app.',
    'Today is ' + $json.body.today + '. Use it to resolve dates that omit the year.',
    'Call the tool exactly once.',
    'Categories: ticket (boarding pass, train/event ticket, reservation), coupon (coupon, loyalty or payment code), shopping (product page, wish list), receipt (order confirmation, receipt, payment), chat (chat, social post), map (map, route, timetable), info (article, recipe, notes), tech (error, settings, code), other.',
    'title: what it is, in ' + ($json.body.language === 'ja' ? 'Japanese' : 'English') + ', max 30 characters, name the shop/app/place if visible.',
    'keywords: up to 12 searchable words. Never include passwords, card numbers or one-time codes.',
    'expires_on: last useful day as YYYY-MM-DD, or null.',
    'important: true only for IDs, contracts, warranties, tax or medical documents, recovery codes.'
  ].join('\n'),
  tools: [{
    name: 'record_screenshot',
    description: 'Save the classification of one screenshot.',
    input_schema: {
      type: 'object',
      properties: {
        category: { type: 'string', enum: ['ticket','coupon','shopping','receipt','chat','map','info','tech','other'] },
        title: { type: 'string' },
        keywords: { type: 'string' },
        expires_on: { type: ['string','null'] },
        important: { type: 'boolean' }
      },
      required: ['category','title','keywords','expires_on','important']
    }
  }],
  tool_choice: { type: 'tool', name: 'record_screenshot' },
  messages: [{ role: 'user', content: [
    { type: 'image', source: { type: 'base64', media_type: $json.body.media_type || 'image/jpeg', data: $json.body.image_base64 } },
    { type: 'text', text: 'Classify this screenshot.' }
  ]}]
}) }}

parameters.jsCode:
const res = $input.first().json;
const call = (res.content || []).find(c => c.type === 'tool_use');
if (!call) throw new Error('Claude returned no classification');
const i = call.input;
const cats = ['ticket','coupon','shopping','receipt','chat','map','info','tech','other'];
const okDate = typeof i.expires_on === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(i.expires_on);
return [{ json: {
  category: cats.includes(i.category) ? i.category : 'other',
  title: String(i.title || '').slice(0, 40),
  keywords: String(i.keywords || '').slice(0, 200),
  expires_on: okDate ? i.expires_on : null,
  important: i.important === true,
} }];
